function toNodes(rules: RuleData[]): Node[] {
  return rules.map(({ selector, wrappers, decls }) => {
    let node: Node = rule(selector, decls.map(([p, v]) => decl(p, v)));
    for (let i = wrappers.length - 1; i >= 0; i--) node = atRule(wrappers[i].name, wrappers[i].params, [node]);
    return node;
  });
}

export function registerTypography(u: UtilityRegistry): void {
  for (const [name, rules] of Object.entries(DATA)) u.static(name, () => toNodes(rules));
}
